package dev.unipi.app

import android.content.Context
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.os.SystemClock
import android.provider.Settings
import android.view.View
import org.json.JSONObject
import kotlin.math.max
import kotlin.math.min
import kotlin.random.Random

/**
 * UNI-200: the Unicrab drawn natively (the Android overlay), from the SAME
 * two files the web renderer uses — `unicrab.sprite.json` (palette, parts,
 * eye masks; generated by apps/mobile/scripts/sprite-from-png.py) and
 * `unicrab.anim.json` (per state: frameMs, whole-cell [dx, dy] per frame and
 * part, eye mask per frame, blink, opacity). build.gradle.kts adds
 * apps/mobile/src/assets/unicrab/ as an asset dir, so there is one copy.
 *
 * Same rules as components/Unicrab.tsx + lib/unicrab.ts: whole-cell moves,
 * `torso` = body + visor + eyes, a random blink every blinkEvery ms, the
 * sleep Z's in the top padding, a still frame 0 when the system turned
 * animations off (developer option / battery saver: animator scale 0).
 */
class UnicrabView(context: Context) : View(context) {
  class Rig(val width: Int, val height: Int, val palette: IntArray, val parts: Map<String, List<IntArray>>, val eyes: Map<String, List<IntArray>>, val anim: JSONObject) {
    companion object {
      fun load(context: Context): Rig {
        fun read(name: String) = context.assets.open(name).bufferedReader().use { it.readText() }
        val sprite = JSONObject(read("unicrab.sprite.json"))
        val anim = JSONObject(read("unicrab.anim.json"))
        val pal = sprite.getJSONArray("palette")
        val palette = IntArray(pal.length()) { Color.parseColor(pal.getString(it)) }
        fun cells(obj: JSONObject): Map<String, List<IntArray>> = obj.keys().asSequence().associateWith { key ->
          val arr = obj.getJSONArray(key)
          (0 until arr.length()).map { i -> arr.getJSONArray(i).let { intArrayOf(it.getInt(0), it.getInt(1), it.getInt(2)) } }
        }
        return Rig(sprite.getInt("width"), sprite.getInt("height"), palette, cells(sprite.getJSONObject("parts")), cells(sprite.getJSONObject("eyes")), anim)
      }
    }
  }

  companion object {
    // lib/unicrab.ts PAD
    const val PAD_LEFT = 2
    const val PAD_RIGHT = 3
    const val PAD_TOP = 4
    const val PAD_BOTTOM = 1
    val STATES = listOf("idle", "working", "needs-you", "done", "offline", "sleep")

    /** lib/unicrab.ts zzzCells: a 4-cell Z above the right claw and a 3-cell one beside it. */
    fun zzz(width: Int, colour: Int): List<IntArray> {
      fun z(x: Int, y: Int, size: Int): List<IntArray> {
        val out = mutableListOf<IntArray>()
        for (i in 0 until size) { out += intArrayOf(x + i, y, colour); out += intArrayOf(x + i, y + size - 1, colour) }
        for (i in 1 until size - 1) out += intArrayOf(x + size - 1 - i, y + i, colour)
        return out
      }
      return z(width - 4, -4, 4) + z(width, 0, 3)
    }
  }

  private val rig = Rig.load(context)
  private val paint = Paint().apply { isAntiAlias = false; style = Paint.Style.FILL }
  private val eyeColour = rig.parts["eye-left"]?.firstOrNull()?.get(2) ?: 0
  private val zzzCells = zzz(rig.width, eyeColour)

  var state: String = "idle"
    set(value) {
      if (field == value || value !in STATES) return
      field = value
      startedAt = SystemClock.uptimeMillis()
      scheduleBlink()
      invalidate()
    }

  private var startedAt = SystemClock.uptimeMillis()
  private var blinking = false
  private var nextBlinkAt = 0L

  private fun stateAnim(): JSONObject = rig.anim.getJSONObject("states").optJSONObject(state) ?: rig.anim.getJSONObject("states").getJSONObject("idle")

  private fun animationsOff(): Boolean =
    Settings.Global.getFloat(context.contentResolver, Settings.Global.ANIMATOR_DURATION_SCALE, 1f) == 0f

  private fun frameCount(a: JSONObject): Int {
    var n = max(1, a.getJSONArray("eyes").length())
    val tracks = a.getJSONObject("tracks")
    for (k in tracks.keys()) n = max(n, tracks.getJSONArray(k).length())
    return n
  }

  private fun offset(a: JSONObject, track: String, frame: Int): IntArray {
    val t = a.getJSONObject("tracks").optJSONArray(track) ?: return intArrayOf(0, 0)
    if (t.length() == 0) return intArrayOf(0, 0)
    val o = t.getJSONArray(min(frame, t.length() - 1))
    return intArrayOf(o.getInt(0), o.getInt(1))
  }

  private fun scheduleBlink() {
    val every = rig.anim.getJSONArray("blinkEvery")
    val lo = every.getInt(0)
    val hi = every.getInt(1)
    nextBlinkAt = SystemClock.uptimeMillis() + lo + Random.nextInt(max(1, hi - lo))
    blinking = false
  }

  init {
    scheduleBlink()
  }

  /** Width / height ratio of the padded sprite (lib/unicrab.ts viewBox). */
  val aspect: Float get() = (rig.width + PAD_LEFT + PAD_RIGHT).toFloat() / (rig.height + PAD_TOP + PAD_BOTTOM).toFloat()

  override fun onDraw(canvas: Canvas) {
    super.onDraw(canvas)
    val a = stateAnim()
    val still = animationsOff()
    val now = SystemClock.uptimeMillis()
    val frameMs = a.getInt("frameMs")
    val frame = if (still) 0 else (((now - startedAt) / frameMs) % frameCount(a)).toInt()
    if (!still && a.optBoolean("blink")) {
      val blinkMs = rig.anim.getInt("blinkMs")
      if (!blinking && now >= nextBlinkAt) blinking = true
      if (blinking && now >= nextBlinkAt + blinkMs) scheduleBlink()
    }
    val cols = rig.width + PAD_LEFT + PAD_RIGHT
    val rows = rig.height + PAD_TOP + PAD_BOTTOM
    // Whole device pixels per cell, centred: crisp at every size.
    val cell = max(1, min(width / cols, height / rows)).toFloat()
    val ox = (width - cell * cols) / 2f + PAD_LEFT * cell
    val oy = (height - cell * rows) / 2f + PAD_TOP * cell
    paint.alpha = 255
    val alpha = (a.optDouble("opacity", 1.0) * 255).toInt()
    val all = offset(a, "all", frame)

    fun draw(cells: List<IntArray>?, track: String?) {
      if (cells == null) return
      val o = if (track != null) offset(a, track, frame) else intArrayOf(0, 0)
      for (c in cells) {
        paint.color = rig.palette.getOrElse(c[2]) { Color.MAGENTA }
        paint.alpha = alpha
        val x = ox + (c[0] + o[0] + all[0]) * cell
        val y = oy + (c[1] + o[1] + all[1]) * cell
        canvas.drawRect(x, y, x + cell, y + cell, paint)
      }
    }

    draw(rig.parts["legs-left"], "legs-left")
    draw(rig.parts["legs-right"], "legs-right")
    draw(rig.parts["body"], "torso")
    draw(rig.parts["visor"], "torso")
    val eyes = a.getJSONArray("eyes")
    val mask = if (blinking && a.optBoolean("blink") && !still) "blink" else eyes.optString(frame % max(1, eyes.length()), "open")
    draw(rig.eyes[mask], "torso")
    draw(rig.parts["claw-left"], "claw-left")
    draw(rig.parts["claw-right"], "claw-right")
    if (state == "sleep") draw(zzzCells, "zzz")

    if (!still) postInvalidateDelayed(min(frameMs.toLong(), 120L))
  }
}
